import React, { useEffect, useMemo, useState } from 'react';
import { getOrgChart, updateOrgChart } from '../services/adminService';
import { toast } from 'react-toastify';

const OrgChart = () => {
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);

  const managerChoicesByUser = useMemo(() => {
    const map = {};
    users.forEach((user) => {
      map[user.id] = users.filter((candidate) => {
        if (candidate.id === user.id) return false;
        if (candidate.department !== user.department) return false;
        return Number(candidate.hierarchyLevel) < Number(user.hierarchyLevel);
      });
    });
    return map;
  }, [users]);

  const managerNameByUser = useMemo(() => {
    return users.reduce((acc, user) => {
      acc[user.id] = user.fullName;
      return acc;
    }, {});
  }, [users]);

  const usersByDepartment = useMemo(() => {
    return users.reduce((acc, user) => {
      const dept = user.department || 'Sans département';
      if (!acc[dept]) acc[dept] = [];
      acc[dept].push(user);
      return acc;
    }, {});
  }, [users]);

  const loadOrgChart = async () => {
    try {
      const data = await getOrgChart();
      const sorted = [...data].sort((a, b) => {
        if (a.department !== b.department) {
          return String(a.department).localeCompare(String(b.department));
        }
        if (Number(a.hierarchyLevel) !== Number(b.hierarchyLevel)) {
          return Number(a.hierarchyLevel) - Number(b.hierarchyLevel);
        }
        return String(a.fullName).localeCompare(String(b.fullName));
      });
      setUsers(sorted);
    } catch (error) {
      toast.error('Erreur lors du chargement de l organigramme');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadOrgChart();
  }, []);

  const handleManagerChange = async (userId, managerId) => {
    try {
      await updateOrgChart(userId, managerId ? Number(managerId) : null);
      setUsers((prev) =>
        prev.map((user) => (user.id === userId ? { ...user, managerId: managerId ? Number(managerId) : null } : user))
      );
      toast.success('Organigramme mis à jour');
    } catch (error) {
      toast.error(error.response?.data?.message || 'Erreur lors de la mise à jour');
    }
  };

  return (
    <div>
      <div className="flex items-center justify-between mb-6">
        <div>
          <h1 className="text-2xl font-bold">Organigramme</h1>
          <p className="text-sm text-gray-500 mt-1">Vue par département et niveau hiérarchique.</p>
        </div>
      </div>

      <div className="space-y-6">
        {loading ? (
          <div className="rounded-3xl border border-gray-200 bg-white p-8 shadow-sm text-center text-gray-600">
            Chargement...
          </div>
        ) : users.length === 0 ? (
          <div className="rounded-3xl border border-dashed border-gray-300 bg-white p-8 text-center text-gray-500">
            Aucun utilisateur actif.
          </div>
        ) : (
          Object.entries(usersByDepartment).map(([department, deptUsers]) => (
            <div key={department} className="rounded-3xl border border-gray-200 bg-white shadow-sm overflow-hidden">
              <div className="bg-blue-50 px-6 py-4 border-b border-blue-100">
                <h2 className="text-lg font-semibold text-blue-900">{department}</h2>
                <p className="text-sm text-blue-700">{deptUsers.length} membre(s) dans ce département</p>
              </div>
              <div className="grid gap-4 p-6 sm:grid-cols-2 xl:grid-cols-3">
                {deptUsers.map((user) => (
                  <div key={user.id} className="rounded-3xl border border-gray-200 bg-white p-5 shadow-sm hover:shadow-md transition-shadow duration-200">
                    <div className="flex items-start justify-between gap-4">
                      <div>
                        <p className="text-base font-semibold text-gray-900">{user.fullName}</p>
                        <p className="text-sm text-gray-500 mt-1">{user.role || 'Rôle non défini'}</p>
                      </div>
                      <span className="rounded-full bg-slate-100 px-3 py-1 text-xs font-medium uppercase tracking-wide text-slate-700">
                        Niveau {user.hierarchyLevel}
                      </span>
                    </div>

                    <div className="mt-4 space-y-2 text-sm text-gray-600">
                      <div>
                        <span className="font-medium text-gray-800">Manager :</span>{' '}
                        {user.managerId ? managerNameByUser[user.managerId] || 'Aucun' : 'Aucun'}
                      </div>
                      {user.email && (
                        <div>
                          <span className="font-medium text-gray-800">Email :</span>{' '}
                          {user.email}
                        </div>
                      )}
                    </div>

                    <div className="mt-5">
                      <label className="block text-sm font-medium text-gray-700">Sélectionner le manager</label>
                      <select
                        value={user.managerId || ''}
                        onChange={(e) => handleManagerChange(user.id, e.target.value)}
                        className="mt-2 w-full rounded-2xl border border-gray-300 bg-white px-3 py-2 text-sm text-gray-800 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500"
                      >
                        <option value="">Aucun</option>
                        {managerChoicesByUser[user.id]?.map((candidate) => (
                          <option key={candidate.id} value={candidate.id}>
                            {candidate.fullName} ({candidate.role})
                          </option>
                        ))}
                      </select>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default OrgChart;
